  CHECK_THAT(  10.00, WithinRel( profiles[0].momentum()[24] ) );
  CHECK_THAT(  15.00, WithinRel( profiles[0].momentum()[25] ) );
  CHECK_THAT(  20.00, WithinRel( profiles[0].momentum()[26] ) );
  CHECK_THAT(  30.00, WithinRel( profiles[0].momentum()[27] ) );
  CHECK_THAT(  40.00, WithinRel( profiles[0].momentum()[28] ) );
  CHECK_THAT(  60.00, WithinRel( profiles[0].momentum()[29] ) );
  CHECK_THAT( 100.00, WithinRel( profiles[0].momentum()[30] ) );
  CHECK_THAT( 8.49E-01, WithinRel( profiles[0].values()[0] ) );
  CHECK_THAT( 8.42E-01, WithinRel( profiles[0].values()[1] ) );
  CHECK_THAT( 8.24E-01, WithinRel( profiles[0].values()[2] ) );
  CHECK_THAT( 7.94E-01, WithinRel( profiles[0].values()[3] ) );
  CHECK_THAT( 7.55E-01, WithinRel( profiles[0].values()[4] ) );
  CHECK_THAT( 6.55E-01, WithinRel( profiles[0].values()[5] ) );
  CHECK_THAT( 5.44E-01, WithinRel( profiles[0].values()[6] ) );
